const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db', { readonly: true });

// List tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));

// Find product-related tables
const productTables = tables.filter(t => t.name.toLowerCase().includes('product'));
productTables.forEach(t => {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log('\nTable:', t.name, '-> Columns:', cols.map(c => c.name));
});
"

