cd /tmp && node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db', { readonly: true });

const product = db.prepare(\"SELECT compatible_with_json FROM products WHERE product_id = 'PROD-2028EE'\").get();
console.log('compatible_with_json:', product.compatible_with_json);

// Parse and look up names of compatible products if any
if (product.compatible_with_json) {
  const compatible = JSON.parse(product.compatible_with_json);
  if (compatible && compatible.length > 0) {
    const placeholders = compatible.map(() => '?').join(',');
    const products = db.prepare('SELECT product_id, name FROM products WHERE product_id IN (' + placeholders + ')').all(...compatible);
    console.log('\nCompatible products:');
    products.forEach(p => console.log('  -', p.product_id, ':', p.name));
  } else {
    console.log('No compatible products listed.');
  }
}

// Also check if any OTHER products list PROD-2028EE as compatible
const others = db.prepare(\"SELECT product_id, name, compatible_with_json FROM products WHERE compatible_with_json LIKE '%PROD-2028EE%'\").all();
if (others.length) {
  console.log('\nProducts that list PROD-2028EE as compatible:');
  others.forEach(p => console.log('  -', p.product_id, ':', p.name));
} else {
  console.log('\nNo other products list PROD-2028EE as compatible.');
}
"

